package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reopens a closed or soft-closed period, by the roles the sheet's reopen permission allows (by default a steward only): its fixed due-total is dropped, so it totals its
 *  claims' current figures again. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!settings.allows(sheetId, request.user(), "reopen")) {
            throw new InvalidPeriodException("Your role may not reopen a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (!period.closed() && !period.softClosed()) {
            throw new InvalidPeriodException("The period " + name + " is not closed");
        }
        periods.reopen(sheetId, name);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Closes an open or soft-closed period, by hand (see {@link PeriodCloser}). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods,
            Settings settings, PeriodCloser closer, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!settings.allows(sheetId, request.user(), "close")) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + name + " is already closed");
        }
        closer.close(sheetId, period, request.user(), false);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.Map;

/** A period: its name and its from and to dates (YYYY-MM-DD, both inclusive); whether it is closed,
 *  the due-total fixed when it was closed ("" while open), and each person's due-total for it fixed
 *  then, by person id (empty while open; a person added later has none); whether it is soft-closed (its figures
 *  fixed as when closed, but its claims still open to change); its cap on each person's OPEN or PENDING claims in it ("" for none); and each person's carried figure for it fixed when
 *  it was closed, by person id (empty while open; a person added later, or a close made before these were kept, has none). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> closedPersonTotals, boolean softClosed, String cap,
        Map<String, String> closedPersonCarried) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's periods; with an as-of date, as they stood at the end of it. */
public class LoadPeriods {
    public void service(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Periods periods, AsOfView view,
            ObjectResponse<List<PeriodResponse>> response) {
        LocalDate date = AsOfView.parse(asOf);
        response.send(date == null ? periods.list(sheetId) : view.periods(sheetId, date));
    }
}
