 *  fixed as when closed, but its claims still open to change); its cap on each person's OPEN or PENDING claims in it ("" for none); and each person's carried figure for it fixed when
 *  it was closed, by person id (empty while open; a person added later, or a close made before these were kept, has none). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> closedPersonTotals, boolean softClosed, String cap,
        Map<String, String> closedPersonCarried) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's periods; with an as-of date, as they stood at the end of it. */
public class LoadPeriods {
    public void service(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Periods periods, AsOfView view,
            ObjectResponse<List<PeriodResponse>> response) {
        LocalDate date = AsOfView.parse(asOf);
