printf 'lock:\n  class: net.officefloor.hq.app.period.LockPeriod\n  govern: [ transaction ]\n' > "$R/lock.POST.yml"
printf 'unlock:\n  class: net.officefloor.hq.app.period.UnlockPeriod\n  govern: [ transaction ]\n' > "$R/unlock.POST.yml"
for kind in Lock Unlock; do
lower=$(echo $kind | tr A-Z a-z); upper=$(echo $kind | tr a-z A-Z)
if [ $kind = Lock ]; then cond='period.locked()'; msg='already locked'; val=true; doc='Locks a period, by a steward only: a locked period cannot be reopened until it is unlocked.'; else cond='!period.locked()'; msg='not locked'; val=false; doc='Unlocks a locked period, by a steward only, so it can be reopened again.'; fi
cat > $P/${kind}Period.java <<EOF
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** $doc */
public class ${kind}Period {
    public void ${lower}(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPeriodException("Only a steward may ${lower} a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if ($cond) {
            throw new InvalidPeriodException("The period " + name + " is $msg");
        }
        periods.setLocked(sheetId, name, $val);
        audit.recordOnCommit("PERIOD_${upper}ED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
EOF
done
